import re,pathlib
def imp(p):
    try: return re.findall(r'^import\s+(AlgebraicJacobian\S*)',p.read_text(),re.M)
    except: return []
seen=set(); q=imp(pathlib.Path('AlgebraicJacobian.lean'))
while q:
    m=q.pop()
    if m in seen: continue
    seen.add(m); q+=imp(pathlib.Path(m.replace('.','/')+'.lean'))
allf={str(p)[:-5].replace('/','.') for p in pathlib.Path('AlgebraicJacobian').rglob('*.lean')}
print("total:",len(allf),"reachable:",len(seen&allf),"unreachable:",len(allf-seen))
